package pro.erez.interstice.client;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.vehicle.Boat;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import pro.erez.interstice.ocean.*;
import pro.erez.interstice.worldgen.IslandWorld;
/** Separate real JVM restores both Sable storage and the partially corroded vanilla boat. */
@EventBusSubscriber(modid="interstice",value=Dist.CLIENT)
public final class LowerToxinWaveColdNative {
    private static final boolean SHORE_ONLY=Boolean.getBoolean("interstice.toxinWavesShoreOnly");private static int chunks;
    private static final boolean ACTIVE=Boolean.getBoolean("interstice.toxinWavesCold");
    private static final JsonObject OUT=new JsonObject();private static JsonObject proof;private static boolean started,closing,finished;private static volatile int phase;private static int exitTicks;private static volatile float shoreYaw,shorePitch;private static long since,deadline;private static ServerLevel level;private static Boat boat;private static Object ship;private static NativeChunkSettler.Session settle;
    private static void require(boolean b,String message){if(!b)throw new IllegalStateException(message);}
    private static void write(){try{Files.writeString(Minecraft.getInstance().gameDirectory.toPath().resolve("toxin-waves-cold.json"),new GsonBuilder().setPrettyPrinting().create().toJson(OUT));}catch(Exception e){throw new IllegalStateException(e);}}
    private static void close(boolean pass,String reason){OUT.addProperty("passed",pass);OUT.addProperty("reason",reason);OUT.addProperty("pid",ProcessHandle.current().pid());write();closing=true;settle=new NativeChunkSettler.Session("wave_cold_after_sable_flush",600,true);try{WaveShipFixture.pause(level);WaveShipFixture.flush(level);}catch(Exception e){OUT.addProperty("passed",false);OUT.addProperty("flush_error",e.toString());write();}}
    @SubscribeEvent public static void client(ClientTickEvent.Post e){if(!ACTIVE)return;var mc=Minecraft.getInstance();if(finished){if(mc.level==null&&mc.screen instanceof TitleScreen&&++exitTicks>=20)mc.stop();return;}if(started){if(mc.player!=null){mc.mouseHandler.releaseMouse();KeyMapping.releaseAll();if(phase>=2){mc.player.setYRot(shoreYaw);mc.player.yRotO=shoreYaw;mc.player.setXRot(shorePitch);mc.player.xRotO=shorePitch;}}return;}if(!(mc.screen instanceof TitleScreen)||mc.getOverlay()!=null)return;try{var path=mc.gameDirectory.toPath();require(path.toRealPath().toString().replace('\\','/').contains("/.verification/"),"Isolated profile");require(!Files.exists(path.resolve("toxin-waves-owner-profile"))&&!Files.exists(path.resolve("toxin-waves-review.json")),"Automated profile only");proof=JsonParser.parseString(Files.readString(path.resolve("toxin-waves.json"))).getAsJsonObject();require(proof.get("passed").getAsBoolean(),"Primary pass required");require(proof.get("pid").getAsLong()!=ProcessHandle.current().pid(),"Separate process required");if(SHORE_ONLY){var prior=JsonParser.parseString(Files.readString(path.resolve("toxin-waves-restoration.json"))).getAsJsonObject();require(prior.get("process_exit_code").getAsInt()==0&&prior.get("restoration_passed").getAsBoolean(),"Prior restoration must have passed in a clean process");OUT.add("restoration_process",prior);OUT.addProperty("restoration_passed",true);OUT.addProperty("scope","shore_visual_after_prior_restoration");}started=true;deadline=System.nanoTime()+java.util.concurrent.TimeUnit.MINUTES.toNanos(8);mc.options.hideGui=true;mc.options.pauseOnLostFocus=false;mc.createWorldOpenFlows().openWorld("toxin-waves-owned",()->{});}catch(Throwable failure){throw new IllegalStateException(failure);}}
    @SubscribeEvent public static void server(ServerTickEvent.Post event){if(!ACTIVE||!started||finished)return;try{var mc=Minecraft.getInstance();if(closing){settle.tick(event.getServer());if(settle.ready()||settle.failed()){OUT.add("settled",settle.report());if(settle.failed()){OUT.addProperty("passed",false);OUT.addProperty("reason",settle.failure());}write();finished=true;mc.execute(()->{if(mc.level!=null)mc.level.disconnect();mc.disconnect(new TitleScreen());});}return;}
        require(System.nanoTime()<deadline,"Cold check deadline");if(level==null){level=event.getServer().getLevel(IslandWorld.TENSION_WORLD);since=level.getGameTime();if(SHORE_ONLY)phase=4;}if(phase==4){for(int n=0;n<3&&chunks<289;n++,chunks++)level.getChunk(chunks%17-8,chunks/17-8);if(chunks<289)return;shore(level);since=level.getGameTime();phase=2;OUT.addProperty("loaded_saved_chunks",chunks);OUT.addProperty("dh_loaded",net.neoforged.fml.ModList.get().isLoaded("distanthorizons"));OUT.addProperty("owner_profile_used",false);}if(phase<2&&level.getGameTime()-since<160)return;
        if(phase==0){level.getChunk(2,0);var saved=level.getEntity(UUID.fromString(proof.get("cold_boat_uuid").getAsString()));require(saved instanceof Boat,"Saved boat missing");boat=(Boat)saved;require(boat.isAlive()&&ToxinBoats.exposure(boat)==73,"Cold reload reset or advanced dry corrosion");int stale=0;for(var extra:level.getEntitiesOfClass(Boat.class,new net.minecraft.world.phys.AABB(32,39,7,43,42,19)))if(extra!=boat&&extra.isNoGravity()&&ToxinBoats.exposure(extra)==73){extra.discard();stale++;}OUT.addProperty("earlier_probe_boats_removed",stale);OUT.addProperty("restored_corrosion",ToxinBoats.exposure(boat));OUT.addProperty("dry_ticks_after_reload",level.getGameTime()-since);
            for(var found:(List<?>)WaveShipFixture.call(WaveShipFixture.container(level),"getAllSubLevels"))if("EREZ toxin wave vessel".equals(WaveShipFixture.call(found,"getName")))ship=found;require(ship!=null,"Sable storage did not restore vessel");double mass=((Number)WaveShipFixture.call(WaveShipFixture.call(ship,"getMassTracker"),"getMass")).doubleValue();require(mass>0,"Restored vessel has no mass");OUT.addProperty("restored_ship_mass",mass);OUT.addProperty("restored_ship_pose",WaveShipFixture.position(ship).toString());require(ToxinHullOcclusion.serverCells>0,"Cold hull occlusion missing");OUT.addProperty("restored_dry_cells",ToxinHullOcclusion.serverCells);boat.setNoGravity(false);boat.setPos(37,35,12);since=level.getGameTime();phase=1;
        }else if(phase==1){require(!boat.isAlive()&&ToxinBoats.exposure(boat)==200,"Corrosion did not continue to exactly 200 after reload");OUT.addProperty("final_corrosion",ToxinBoats.exposure(boat));OUT.addProperty("dh_loaded",net.neoforged.fml.ModList.get().isLoaded("distanthorizons"));OUT.addProperty("owner_profile_used",false);shore(level);since=level.getGameTime();phase=2;}
        else if(phase==2){if(level.getGameTime()-since<40)return;mc.execute(()->Screenshot.grab(mc.gameDirectory,"toxin-waves-shore-cold.png",mc.getMainRenderTarget(),unused->{}));since=level.getGameTime();phase=3;}
        else if(phase==3){if(level.getGameTime()-since<20)return;close(true,"");}
    }catch(Throwable failure){failure.printStackTrace();close(false,failure.toString());}}
    private static void shore(ServerLevel w){double best=Double.POSITIVE_INFINITY,cx=0,cz=0;int aimX=0,aimZ=1;int y=(int)LowerToxinSurface.base(w);for(int x=-64;x<=128;x++)for(int z=-64;z<=128;z++)if(LowerToxinSurface.cell(w,x,z))for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){var p=new net.minecraft.core.BlockPos(x+d[0],y,z+d[1]);if(!w.hasChunkAt(p)||!(w.getBlockState(p).isCollisionShapeFullBlock(w,p)||w.getBlockState(p.below()).isCollisionShapeFullBlock(w,p.below())||w.getBlockState(p.above()).isCollisionShapeFullBlock(w,p.above())||w.getBlockState(p.above(2)).isCollisionShapeFullBlock(w,p.above(2))))continue;int xx=x-d[0]*6,zz=z-d[1]*6;if(!LowerToxinSurface.cell(w,xx,zz)||LowerToxinSurface.mask(w,xx+.5,zz+.5)<.9)continue;double distance=(xx-43.0)*(xx-43.0)+(zz-14.0)*(zz-14.0);if(distance<best){best=distance;cx=xx+.5;cz=zz+.5;aimX=d[0];aimZ=d[1];}}require(Double.isFinite(best),"No loaded natural shoreline for visual proof");shoreYaw=(float)Math.toDegrees(Math.atan2(-aimX,aimZ));shorePitch=25;var mc=Minecraft.getInstance();var player=w.getServer().getPlayerList().getPlayer(mc.player.getUUID());player.teleportTo(w,cx,LowerToxinSurface.base(w)+2.5,cz,Set.of(),shoreYaw,shorePitch);player.hasChangedDimension();player.getAbilities().flying=true;player.onUpdateAbilities();OUT.addProperty("shore_camera",cx+","+(LowerToxinSurface.base(w)+2.5)+","+cz);OUT.addProperty("shore_yaw",shoreYaw);OUT.addProperty("shore_open_mask",LowerToxinSurface.mask(w,cx,cz));}
    private LowerToxinWaveColdNative(){}
}
